Here's an example of blocking read() function call being interrupted by a signal and how to handle it using EINTR error handling:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

#define PORT 8080
#define BUFFER_SIZE 1024

void signal_handler(int signal) {
    printf("Signal received: %d\n", signal);
}

int main() {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation failed");
        return -1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(sock, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connect failed");
        return -1;
    }

    signal(SIGINT, signal_handler);

    char buffer[BUFFER_SIZE];
    int bytes_read = 0;

    while (1) {
        bytes_read = read(sock, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            if (errno == EINTR) {
                printf("Read interrupted by signal, retrying...\n");
                continue;
            }
            perror("Read failed");
            return -1;
        }
        if (bytes_read == 0) {
            printf("Connection closed\n");
            return 0;
        }
        printf("Received: %s\n", buffer);
    }

    close(sock);
    return 0;
}
```

In this example, we handle the SIGINT signal (e.g., Ctrl+C) using the signal_handler() function. When a signal is received, the signal_handler() function is called, and it prints a message indicating that the signal has been received.

In the main() function, we use a loop to read data from the socket. If the read() function is interrupted by a signal, it returns -1 with errno set to EINTR. We check for this error, and if it occurs, we print a message indicating that the read has been interrupted and continue with the next iteration of the loop. This allows us to retry the read operation after the signal has been handled.

The read() function continues to be called until the connection is closed (when bytes_read is 0), or an error occurs (when bytes_read is less than 0 and errno is not EINTR).

