Here is a sample C# function that uses OpenXML SDK to merge two Word documents into one. This function assumes that the first document (source document) contains the first 2 pages, header, footer, and design (fonts and styles), and the second document (target document) contains only page contents and glossary. Both documents may contain images.

```csharp
using DocumentFormat.OpenXml;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;
using System;
using System.IO;
using System.Linq;

public class WordDocumentMerger
{
    public void MergeWordDocuments(string sourceDocumentPath, string targetDocumentPath, string outputDocumentPath)
    {
        using (WordprocessingDocument sourceDoc = WordprocessingDocument.Open(sourceDocumentPath, true))
        {
            using (WordprocessingDocument targetDoc = WordprocessingDocument.Open(targetDocumentPath, true))
            {
                MainDocumentPart sourceMainPart = sourceDoc.MainDocumentPart;
                MainDocumentPart targetMainPart = targetDoc.MainDocumentPart;

                // Copy the header, footer, and design (fonts and styles) from the source document
                sourceMainPart.HeaderParts.CloneContent(targetMainPart.HeaderParts);
                sourceMainPart.FooterParts.CloneContent(targetMainPart.FooterParts);
                targetMainPart.StyleDefinitionsPart.CloneContent(sourceMainPart.StyleDefinitionsPart);

                // Copy the first 2 pages from the source document
                int sourcePageCount = sourceMainPart.Document.Body.Elements<Section>().First().Body.Elements<Paragraph>().Count();
                for (int i = 0; i < Math.Min(2, sourcePageCount); i++)
                {
                    Paragraph sourceParagraph = sourceMainPart.Document.Body.Elements<Section>().First().Body.Elements<Paragraph>().ElementAt(i);
                    targetMainPart.Document.Body.Append(sourceParagraph);
                }

                // Add the page contents from the target document
                foreach (Paragraph targetParagraph in targetMainPart.Document.Body.Elements<Section>().First().Body.Elements<Paragraph>())
                {
                    targetMainPart.Document.Body.Append(targetParagraph);
                }

                // Add the glossary from the target document
                if (targetMainPart.GlossaryDocumentPart != null)
                {
                    targetMainPart.MainDocumentPart.Append(targetMainPart.GlossaryDocumentPart);
                }

                // Copy the images from the source document
                foreach (ImagePart sourceImagePart in sourceDoc.MainDocumentPart.ImageParts)
                {
                    string sourceImageUri = sourceDoc.MainDocumentPart.GetIdOfPart(sourceImagePart);
                    ImagePart targetImagePart = targetMainPart.ImageParts.Add(sourceImagePart);
                    targetMainPart.MainDocumentPart.AddTargetPart(targetImagePart);
                    targetMainPart.MainDocumentPart.XmlnsSdt.Add(new Uri(sourceImageUri));
                }

                // Save the output document
                targetMainPart.Document.Save();
            }
        }
    }
}
```

This function assumes that both documents are in the same format (docx). The function opens both documents, copies the header, footer, and design from the source document to the target document, copies the first 2 pages from the source document to the target document, adds the page contents from the target document, and adds the glossary from the target document. It also copies the images from the source document. Finally, it saves the merged document to a new file.

You can use this function like this:

```csharp
WordDocumentMerger merger = new WordDocumentMerger();
merger.MergeWordDocuments("sourceDocument.docx", "targetDocument.docx", "outputDocument.docx");
```

This will merge the two documents and save the result to "outputDocument.docx".

