Here is an example of GLSL code for old-school raycasting in a vertex and fragment shader:

**Vertex Shader**
```glsl
#version 330 core

in vec3 position;
in vec3 direction;
in float ray_length;

uniform mat4 projection;
uniform mat4 view;

out vec3 ray_direction;
out float ray_distance;

void main() {
    // Calculate the ray direction and distance
    ray_direction = normalize(direction);
    ray_distance = ray_length;

    // Convert the ray direction to view space
    vec3 view_direction = (view * vec4(ray_direction, 0)).xyz;

    // Convert the view direction to clip space
    vec4 clip_direction = projection * vec4(view_direction, 1);

    // Output the ray direction and distance in clip space
    gl_Position = clip_direction;
    ray_direction = view_direction;
    ray_distance = ray_length;
}
```
**Fragment Shader**
```glsl
#version 330 core

in vec3 ray_direction;
in float ray_distance;
in vec4 color;

uniform sampler2D texture;
uniform vec2 screen_size;

