```
#include <Metal/Metal.h>
#include <simd/simd.h>

// Define the blur kernel function
kernel void gaussianBlur(
    device float* input [[buffer(0)]], // input image
    device float* output [[buffer(1)]], // output image
    constant float* kernel [[buffer(2)]], // Gaussian kernel coefficients
    constant int2 size [[buffer(3)]], // image size
    constant float sigma [[buffer(4)]], // Gaussian blur sigma
    uint2 id [[threadposition]]) {

    // Calculate the center pixel coordinates
    int2 center = id + size / 2;

    // Initialize the output pixel value
    float4 outputPixel = 0;

    // Iterate over the Gaussian kernel
    for (int x = -3; x <= 3; x++) {
        for (int y = -3; y <= 3; y++) {
            // Calculate the offset from the center pixel
            int2 offset = int2(x, y);

            // Calculate the weight of this kernel sample
            float weight = kernel[(x + 3) * 9 + y + 3];

            // Sample the input image at the offset position
            float4 inputPixel = input[center.y + offset.y * size.x + center.x + offset.x];

            // Accumulate the contribution of this kernel sample
            outputPixel += inputPixel * weight;
        }
    }

    // Normalize the output pixel value
    outputPixel /= kernel[36]; // Assuming a 9x9 kernel

    // Store the output pixel value
    output[center.y * size.x + center.x] = outputPixel.rgb;
}
```
