import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [todos, setTodos] = useState([]);
  const [newTodo, setNewTodo] = useState('');
  const [editing, setEditing] = useState(null);

  useEffect(() => {
    axios.get('http://localhost:3000/api/todos')
      .then(response => {
        setTodos(response.data);
      });
  }, []);

  const handleAddTodo = () => {
    axios.post('http://localhost:3000/api/todos', { text: newTodo })
      .then(response => {
        setTodos([...todos, response.data]);
        setNewTodo('');
      });
  };

  const handleEditTodo = (id) => {
    setEditing(id);
  };

  const handleUpdateTodo = (id, text) => {
    axios.put(`http://localhost:3000/api/todos/${id}`, { text })
      .then(response => {
        setTodos(todos.map((todo) => (todo.id === id ? response.data : todo)));
        setEditing(null);
      });
  };

  const handleDeleteTodo = (id) => {
    axios.delete(`http://localhost:3000/api/todos/${id}`)
      .then(() => {
        setTodos(todos.filter((todo) => todo.id !== id));
      });
  };

  return (
    <div>
      <h1>To-Do List</h1>
      <input
        type="text"
        value={newTodo}
        onChange={(e) => setNewTodo(e.target.value)}
        placeholder="Add new todo"
      />
      <button onClick={handleAddTodo}>Add</button>
      <ul>
        {todos.map((todo) => (
          <li key={todo.id}>
            {editing === todo.id ? (
              <input
                type="text"
                value={todo.text}
                onChange={(e) => handleUpdateTodo(todo.id, e.target.value)}
                placeholder="Edit todo"
              />
            ) : (
              <span>{todo.text}</span>
            )}
            {editing === todo.id ? (
              <button onClick={() => handleUpdateTodo(todo.id, todo.text)}>Save</button>
            ) : (
              <button onClick={() => handleEditTodo(todo.id)}>Edit</button>
            )}
            <button onClick={() => handleDeleteTodo(todo.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
```
