  // Perform forward pass
  for (int i = 0; i < NUM_NEURONS; i++) {
    float sum = 0.0f;
    for (int j = 0; j < HIDDEN_NEURONS; j++) {
      sum += input[i] * weights[j * NUM_NEURONS + i];
    }
    sum += bias[j];
    out_data.write(sum);
  }
}

// Define the main function
void mnist_main(hls::stream<float> &in_data,
                hls::stream<float> &out_data) {
