Create a new class that inherits from `MKInputAccessoryView`. This class will be responsible for displaying the two buttons:
```swift
class ButtonInputAccessoryView: MKInputAccessoryView {
    let button1 = MKButton(title: "Button 1", style: .primary)
    let button2 = MKButton(title: "Button 2", style: .primary)

    override init(frame: CGRect) {
        super.init(frame: frame)
        setupView()
    }

    required init?(coder: NSCoder) {
        super.init(coder: coder)
        setupView()
    }

    func setupView() {
        addSubview(button1)
        addSubview(button2)

        button1.translatesAutoresizingMaskIntoConstraints = false
        button2.translatesAutoresizingMaskIntoConstraints = false

        NSLayoutConstraint.activate([
            button1.leadingAnchor.constraint(equalTo: leadingAnchor),
            button1.topAnchor.constraint(equalTo: topAnchor),
            button1.trailingAnchor.constraint(equalTo: trailingAnchor),
            button1.heightAnchor.constraint(equalTo: heightAnchor, multiplier: 0.5),

            button2.leadingAnchor.constraint(equalTo: leadingAnchor),
            button2.topAnchor.constraint(equalTo: button1.bottomAnchor),
            button2.trailingAnchor.constraint(equalTo: trailingAnchor),
            button2.heightAnchor.constraint(equalTo: heightAnchor, multiplier: 0.5)
        ])
    }
}
```
**Step 4: Implement the input accessory view delegate**

Implement the `MKInputAccessoryViewDelegate` protocol to handle button taps:
```swift
extension ButtonInputAccessoryView: MKInputAccessoryViewDelegate {
    func inputAccessoryView(_ inputAccessoryView: MKInputAccessoryView, didTap button: MKButton) {
        if button == button1 {
            // Button 1 tapped
        } else if button == button2 {
            // Button 2 tapped
        }
    }
}
```
**Step 5: Register the input accessory view with the message input controller**

In your `ButtonExtension` file, add the following code to register the input accessory view:
```swift
class ButtonExtension: NSObject, MKExtension {
    lazy var inputAccessoryView: ButtonInputAccessoryView = {
        let view = ButtonInputAccessoryView()
        view.delegate = self
        return view
    }()

    func sendMessageInputControllerDidShow(_ controller: MKSendMessageInputController) {
        controller.inputAccessoryView = inputAccessoryView
    }
}
```
