  .then((response) => response.text())
  .then((html) => {
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
    a.download = 'page.html';
    a.style.display = 'none';
    document.body.appendChild(a);
