```javascript
function findObjectByPath(obj, target, path = '') {
    // Convert the object to an array
    const stack = [Object.entries(obj)];

    // Continue until the stack is empty
    while (stack.length > 0) {
        // Get the current array
        const entries = stack.pop();

        // Iterate over each entry in the array
        for (const [key, value] of entries) {
            // Construct the current path
            const newPath = path ? `${path}.${key}` : key;

            // If the value is an object, add it to the stack with the new path
            if (typeof value === 'object') {
                stack.push(Object.entries(value));
            }

            // If the value matches the target, return the new path
            if (value.name === target) {
                return newPath;
            }
        }
    }

    // If the target is not found, return null
    return null;
}

// Example usage:
