```javascript
const { Readable } = require('stream');

class PullStream extends Readable {
  constructor(options) {
    super(options);
    this._buf = Buffer.alloc(0);
    this._ended = false;
  }

  _read(size) {
    if (this._ended) {
      this.push(null);
      return;
    }
    // Simulate some data being available
    const chunk = Buffer.alloc(size);
    // You would typically get data from an external source here
    // For this example, we'll just generate some random data
    for (let i = 0; i < size; i++) {
      chunk[i] = Math.floor(Math.random() * 256);
    }
    this._buf = Buffer.concat([this._buf, chunk]);
    this.push(chunk);
  }

  end() {
    this._ended = true;
    this.push(null);
  }

  // Optionally, you can implement a method to get the available data
  available() {
    return this._buf.length;
  }
}

// Create a new pull stream
const stream = new PullStream();

// Set up a listener for when data is available
stream.on('data', (chunk) => {
  console.log(`Received chunk of length ${chunk.length}`);
});

