import java.util.Scanner;

public class GCD {
    public static void main(String[] args) {
        // Create a Scanner object to get user input
        Scanner scanner = new Scanner(System.in);

        // Prompt the user to enter two positive integers
        System.out.print("Enter the first positive integer: ");
        int num1 = getPositiveInteger(scanner);

        System.out.print("Enter the second positive integer: ");
        int num2 = getPositiveInteger(scanner);

        // Calculate and display the GCD
        int gcd = calculateGCD(num1, num2);
        System.out.println("The GCD of " + num1 + " and " + num2 + " is: " + gcd);
    }

    /**
     * Prompts the user to enter a positive integer and returns the input value.
     * 
     * @param scanner Scanner object to get user input
     * @return A positive integer entered by the user
     */
    private static int getPositiveInteger(Scanner scanner) {
        int num;
        while (true) {
            try {
                num = scanner.nextInt();
                if (num > 0) {
                    break;
                } else {
                    System.out.print("Please enter a positive integer: ");
                }
            } catch (Exception e) {
                System.out.print("Invalid input. Please enter a positive integer: ");
                scanner.next(); // Clear the invalid input
            }
        }
        return num;
    }

    /**
     * Calculates the GCD of two numbers using the Euclidean algorithm.
     * 
     * @param num1 The first number
     * @param num2 The second number
     * @return The GCD of num1 and num2
     */
    private static int calculateGCD(int num1, int num2) {
