Here's a simple implementation of a Recurrent Neural Network (RNN) using plain TypeScript.

### RNN Implementation

```typescript
// Define the structure of a neuron
class Neuron {
  private inputs: number[];
  private weights: number[];
  private bias: number;
  private output: number;

  constructor(inputDim: number, outputDim: number) {
    // Initialize weights and bias randomly
    this.weights = new Array(inputDim).fill(0).map(() => Math.random() * 2 - 1);
    this.bias = Math.random() * 2 - 1;
  }

  update(inputs: number[]): void {
    // Calculate the weighted sum of inputs
    let weightedSum = 0;
    for (let i = 0; i < inputs.length; i++) {
      weightedSum += inputs[i] * this.weights[i];
    }

    // Add bias to the weighted sum
    weightedSum += this.bias;

    // Apply the activation function (in this case, sigmoid)
    this.output = 1 / (1 + Math.exp(-weightedSum));
  }

  getOutput(): number {
    return this.output;
  }
}

// Define the structure of an RNN cell
class RNNCell {
  private inputNeuron: Neuron;
  private forgetNeuron: Neuron;
  private cellStateNeuron: Neuron;
  private outputNeuron: Neuron;

  constructor(inputDim: number, outputDim: number) {
    this.inputNeuron = new Neuron(inputDim, outputDim);
    this.forgetNeuron = new Neuron(outputDim, outputDim);
    this.cellStateNeuron = new Neuron(outputDim, outputDim);
    this.outputNeuron = new Neuron(outputDim, outputDim);
  }

  update(inputs: number[], prevState: number[], cellState: number[]): void {
    // Update the input neuron
    this.inputNeuron.update(inputs);

    // Update the forget neuron
    this.forgetNeuron.update([prevState[0], cellState[0]]);

    // Update the cell state neuron
    this.cellStateNeuron.update([prevState[1], this.forgetNeuron.getOutput(), this.inputNeuron.getOutput()]);

    // Update the output neuron
    this.outputNeuron.update([prevState[0], this.cellStateNeuron.getOutput()]);

    // Update the cell state and previous state
    cellState[0] = this.cellStateNeuron.getOutput();
    prevState[0] = this.outputNeuron.getOutput();

    // Store the updated cell state and previous state
    this.prevState = prevState;
    this.cellState = cellState;
  }

  getOutput(): number[] {
    return [this.prevState[0], this.cellState[0]];
  }

  private prevState: number[] = [0, 0];
  private cellState: number[] = [0, 0];
}

// Define the RNN class
class RNN {
  private cells: RNNCell[];

  constructor(inputDim: number, outputDim: number, numCells: number) {
    this.cells = new Array(numCells).fill(0).map(() => new RNNCell(inputDim, outputDim));
  }

  update(inputs: number[]): number[] {
    let prevState: number[] = [0, 0];
    let cellState: number[] = [0, 0];

    for (let i = 0; i < this.cells.length; i++) {
      this.cells[i].update(inputs, prevState, cellState);
      prevState = this.cells[i].getOutput();
    }

    return prevState;
  }
}
```

### Example Usage

```typescript
