Here's a JavaScript function that uses recursion to search a JSON object for a specified key. It returns an array of objects, where each object contains the key's value and the JSON key path.

```javascript
function searchJson(json, key) {
    let result = [];

    function recursiveSearch(obj, path) {
        for (let k in obj) {
            if (k === key) {
                result.push({ value: obj[k], path: path + '.' + k });
            } else if (typeof obj[k] === 'object') {
                recursiveSearch(obj[k], path + '.' + k);
            }
        }
    }

    recursiveSearch(json, '');

    return result;
}
```

