    auth_url = f'{qbittorrent_url}/api/v2/auth/login'
    auth_data = {
        'username': qbittorrent_user,
        'password': qbittorrent_pass
    }
    response = requests.post(auth_url, data=json.dumps(auth_data), headers={'Content-Type': 'application/json'})
    if response.status_code == 200:
        return response.json()['token']
    else:
        print(f'Failed to login: {response.text}')
        return None

# Get all torrents
def get_all_torrents(token):
    torrents_url = f'{qbittorrent_url}/api/v2/torrents/torrents'
    headers = {'X-Transmission-Session-Id': token}
    response = requests.get(torrents_url, headers=headers)
    if response.status_code == 200:
        return response.json()['torrents']
    else:
        print(f'Failed to get torrents: {response.text}')
        return []

# Remove tracker from a torrent
def remove_tracker_from_torrent(token, torrent_id, tracker_to_remove):
    torrents_url = f'{qbittorrent_url}/api/v2/torrents/torrents/{torrent_id}'
    data = {
        'tracker-remove': tracker_to_remove
    }
    headers = {'X-Transmission-Session-Id': token}
    response = requests.post(torrents_url, data=json.dumps(data), headers={'Content-Type': 'application/json', **headers})
