const boundingBox = svg.getBBox();

console.log(boundingBox);
```
However, if you have deeply nested SVG elements, you'll need to traverse the DOM tree to find the desired element. You can use a recursive function to achieve this:

```javascript
function getBoundingBox(element) {
  if (element.getBBox) {
    return element.getBBox();
  } else {
    // Traverse child elements
    for (let child of element.children) {
      const boundingBox = getBoundingBox(child);
      if (boundingBox) {
        return boundingBox;
      }
    }
  }
  return null;
}

const svg = document.querySelector('svg');
const boundingBox = getBoundingBox(svg);

console.log(boundingBox);
```
This recursive function will traverse the DOM tree and return the bounding box of the first element that has a `getBBox()` method.

