Here's a Python program that implements a simple data storage oriented blockchain with the specified requirements:

```python
import hashlib
import time

class Block:
    def __init__(self, index, previous_hash, timestamp, data, hash):
        self.index = index
        self.previous_hash = previous_hash
        self.timestamp = timestamp
        self.data = data
        self.hash = hash

def calculate_hash(index, previous_hash, timestamp, data):
    return hashlib.sha256(f'{index}{previous_hash}{timestamp}{data}'.encode('utf-8')).hexdigest()

def create_genesis_block():
    return Block(0, '0', time.time(), 'Genesis Block', calculate_hash(0, '0', time.time(), 'Genesis Block'))

def create_new_block(previous_block, data, deposit):
    index = previous_block.index + 1
    timestamp = time.time()
    hash = calculate_hash(index, previous_block.hash, timestamp, data)
    return Block(index, previous_block.hash, timestamp, {'data': data, 'deposit': deposit}, hash)

class Node:
    def __init__(self, node_id):
        self.node_id = node_id
        self.blockchain = [create_genesis_block()]
        self.balance = 0

    def add_data(self, data, deposit):
        data_size = len(data.encode('utf-8'))
        data_lifetime = deposit / data_size
        new_block = create_new_block(self.blockchain[-1], data, deposit)
        self.blockchain.append(new_block)
        self.balance += deposit

    def access_data(self, index, fee):
        if index < len(self.blockchain):
            self.balance += fee
            return self.blockchain[index].data
        else:
            return None

    def delete_data(self, index):
        if index < len(self.blockchain):
            data_deposit = self.blockchain[index].data['deposit']
            self.balance -= data_deposit
            self.blockchain[index].data = None
            return data_deposit
        else:
            return None

def distribute_rewards(nodes, deposit):
    reward = deposit / len(nodes)
    for node in nodes:
        node.balance += reward

def main():
    nodes = [Node(i) for i in range(3)]

    # Node 0 adds data
    nodes[0].add_data('Hello, Blockchain!', 100)
    distribute_rewards(nodes, 100)

    # Node 1 accesses data from Node 0
    print(nodes[1].access_data(1, 10))

    # Node 0 deletes data
    refund = nodes[0].delete_data(1)
    print(f'Refund: {refund}')

    # Print node balances
    for i, node in enumerate(nodes):
        print(f'Node {i} balance: {node.balance}')

if __name__ == '__main__':
    main()
```

This program creates a simple blockchain with data storage and rewards for node owners who host data. The `Node` class represents a node in the network, and the `Block` class represents a block in the blockchain. The `add_data`, `access_data`, and `delete_data` methods in the `Node` class implement the required functionality for adding, accessing, and deleting data from the blockchain. The `distribute_rewards` function is used to distribute rewards evenly across all nodes hosting the data.

**Simple Flask Web Server with HTTP Basic Authentication**
===========================================================

Below is an example of a simple Flask web server that uses HTTP basic authentication with a Python dictionary to store login credentials. The server also includes an index page.

```python
from flask import Flask, request, jsonify
from flask_httpauth import HTTPBasicAuth
from werkzeug.security import check_password_hash

app = Flask(__name__)
auth = HTTPBasicAuth()

# Dictionary to store login credentials
users = {
    "user1": "password1",
    "user2": "password2"
}

# Convert passwords to hashed versions for secure storage
hashed_users = {user: hash for user, hash in users.items()}

@auth.verify_password
def verify_password(username, password):
    """Verify password for a given username."""
    if username in hashed_users:
        return check_password_hash(hashed_users[username], password)
    return False

@app.route('/')
@auth.login_required
def index():
    """Index page that requires authentication."""
    return "Hello, {}!".format(request.authorization.username)

if __name__ == '__main__':
    app.run(debug=True)
```

However, please note that the code above does not actually hash the passwords. It just stores them as is, which is insecure. 

Here is a revised version that hashes the passwords:

```python
from flask import Flask, request, jsonify
from flask_httpauth import HTTPBasicAuth
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
auth = HTTPBasicAuth()

# Dictionary to store login credentials
users = {
    "user1": generate_password_hash("password1"),
    "user2": generate_password_hash("password2")
}

@auth.verify_password
def verify_password(username, password):
    """Verify password for a given username."""
    if username in users:
        return check_password_hash(users[username], password)
    return False

@app.route('/')
@auth.login_required
def index():
    """Index page that requires authentication."""
    return "Hello, {}!".format(request.authorization.username)

if __name__ == '__main__':
    app.run(debug=True)
```

**Example Usage:**

1. Run the Flask application.
2. Open a web browser and navigate to `http://localhost:5000/`.
3. You will be prompted to enter a username and password. Enter `user1` and `password1` (or `user2` and `password2`).
4. If the credentials are correct, you will see a greeting message with your username.

Note: This is a very basic example and should not be used in production without proper security measures, such as using a secure password hashing algorithm and protecting against common web vulnerabilities.

