    this.sourcePort = (tcpBuffer[0] << 8) | tcpBuffer[1];
    this.destinationPort = (tcpBuffer[2] << 8) | tcpBuffer[3];
    this.sequenceNumber = (tcpBuffer[4] << 24) | (tcpBuffer[5] << 16) | (tcpBuffer[6] << 8) | tcpBuffer[7];
    this.acknowledgementNumber = (tcpBuffer[8] << 24) | (tcpBuffer[9] << 16) | (tcpBuffer[10] << 8) | tcpBuffer[11];

