    this.flags = {
      URG: (flagsByte & 0x20) !== 0,
      ACK: (flagsByte & 0x10) !== 0,
      PSH: (flagsByte & 0x08) !== 0,
      RST: (flagsByte & 0x04) !== 0,
      SYN: (flagsByte & 0x02) !== 0,
      FIN: (flagsByte & 0x01) !== 0,
    };

    // Parse the window and checksum
    this.window = (tcpBuffer[14] << 8) | tcpBuffer[15];
    this.checksum = (tcpBuffer[16] << 8) | tcpBuffer[17];

    // Parse the urgent pointer
    this.urgentPointer = (tcpBuffer[18] << 8) | tcpBuffer[19];

    // Parse the options
    const dataOffset = (tcpBuffer[12] >> 4) * 4;
    this.options = tcpBuffer.slice(20, dataOffset);

    // Parse the data
    this.data = tcpBuffer.slice(dataOffset);
  }

  public serialize(): Uint8Array {
    // Serialize the TCP header
    const tcpBuffer = new Uint8Array(20 + this.options.length + this.data.length);
    tcpBuffer[0] = (this.sourcePort >> 8) & 0xff;
    tcpBuffer[1] = this.sourcePort & 0xff;
    tcpBuffer[2] = (this.destinationPort >> 8) & 0xff;
    tcpBuffer[3] = this.destinationPort & 0xff;
    tcpBuffer[4] = (this.sequenceNumber >> 24) & 0xff;
    tcpBuffer[5] = (this.sequenceNumber >> 16) & 0xff;
    tcpBuffer[6] = (this.sequenceNumber >> 8) & 0xff;
    tcpBuffer[7] = this.sequenceNumber & 0xff;
    tcpBuffer[8] = (this.acknowledgementNumber >> 24) & 0xff;
    tcpBuffer[9] = (this.acknowledgementNumber >> 16) & 0xff;
    tcpBuffer[10] = (this.acknowledgementNumber >> 8) & 0xff;
    tcpBuffer[11] = this.acknowledgementNumber & 0xff;

