    if (this.flags.URG) flagsByte |= 0x20;
    if (this.flags.ACK) flagsByte |= 0x10;
    if (this.flags.PSH) flagsByte |= 0x08;
    if (this.flags.RST) flagsByte |= 0x04;
    if (this.flags.SYN) flagsByte |= 0x02;
    if (this.flags.FIN) flagsByte |= 0x01;
    tcpBuffer[12] = (this.dataOffset << 4) | flagsByte;

    // Serialize the window and checksum
    tcpBuffer[14] = (this.window >> 8) & 0xff;
    tcpBuffer[15] = this.window & 0xff;
    tcpBuffer[16] = (this.checksum >> 8) & 0xff;
    tcpBuffer[17] = this.checksum & 0xff;

    // Serialize the urgent pointer
    tcpBuffer[18] = (this.urgentPointer >> 8) & 0xff;
    tcpBuffer[19] = this.urgentPointer & 0xff;

    // Serialize the options
    tcpBuffer.set(this.options, 20);

    // Serialize the data
    tcpBuffer.set(this.data, 20 + this.options.length);

    return tcpBuffer;
  }
