class CoroutineManager {
    private $maxRunning;
    private $semaphore;

    public function __construct(int $maxRunning) {
        $this->maxRunning = $maxRunning;
        $this->semaphore = new SynchronizedCounter($maxRunning);
    }

    public function run(Fiber $fiber): void {
        $this->semaphore->acquire();
        $fiber->start();
    }

    public function addJob(callable $job): void {
        $fiber = new Fiber($job);
        $this->run($fiber);
    }
}

class SynchronizedCounter {
    private $count;
    private $mutex;

    public function __construct(int $initialCount) {
        $this->count = $initialCount;
        $this->mutex = new Mutex();
    }

    public function acquire(): void {
        $this->mutex->lock();
        while ($this->count <= 0) {
            $this->mutex->wait();
        }
        $this->count--;
        $this->mutex->unlock();
    }

    public function release(): void {
        $this->mutex->lock();
        $this->count++;
        $this->mutex->notify();
        $this->mutex->unlock();
    }
}

$manager = new CoroutineManager(5);

for ($i = 0; $i < 10; $i++) {
    $job = function (int $id) use ($manager) {
        echo "Job $id started\n";
        // Simulate some work
        sleep(1);
        echo "Job $id finished\n";
        // Release the semaphore when the job is done
        $manager->semaphore->release();
    };

    $manager->addJob(function () use ($job, $i) {
        $job($i);
    });
