class SpriteEditor {
  constructor(canvasId) {
    this.canvas = document.getElementById(canvasId);
    this.ctx = this.canvas.getContext('2d');
    this.sprites = [];
    this.selectedSprite = null;
    this.tool = 'select';

    // Initialize canvas dimensions
    this.canvas.width = 800;
    this.canvas.height = 600;

    // Bind event listeners
    this.canvas.addEventListener('mousedown', (e) => this.handleMouseDown(e));
    this.canvas.addEventListener('mousemove', (e) => this.handleMouseMove(e));
    this.canvas.addEventListener('mouseup', (e) => this.handleMouseUp(e));

    // Initialize toolbar
    this.toolbar = document.getElementById('toolbar');
    this.toolbar.addEventListener('click', (e) => this.handleToolbarClick(e));
  }

  // Create a new sprite
  createSprite(x, y, width, height) {
    const sprite = {
      x,
      y,
      width,
      height,
      color: 'rgba(255, 0, 0, 1)',
    };
    this.sprites.push(sprite);
    return sprite;
  }

  // Draw all sprites on the canvas
  drawSprites() {
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    this.sprites.forEach((sprite) => {
      this.ctx.fillStyle = sprite.color;
      this.ctx.fillRect(sprite.x, sprite.y, sprite.width, sprite.height);
    });
  }

  // Handle mouse down event
  handleMouseDown(e) {
    const rect = this.canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (this.tool === 'create') {
      this.createSprite(x, y, 50, 50);
    } else if (this.tool === 'select') {
      this.selectedSprite = this.getSpriteAt(x, y);
    }
  }

  // Handle mouse move event
  handleMouseMove(e) {
    const rect = this.canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (this.selectedSprite) {
      this.selectedSprite.x = x;
      this.selectedSprite.y = y;
      this.drawSprites();
    }
  }

  // Handle mouse up event
  handleMouseUp(e) {
    this.selectedSprite = null;
  }

  // Get the sprite at the specified coordinates
  getSpriteAt(x, y) {
    for (const sprite of this.sprites) {
      if (x >= sprite.x && x <= sprite.x + sprite.width && y >= sprite.y && y <= sprite.y + sprite.height) {
        return sprite;
      }
    }
    return null;
  }

  // Handle toolbar click event
  handleToolbarClick(e) {
    if (e.target.id === 'create-tool') {
      this.tool = 'create';
    } else if (e.target.id === 'select-tool') {
      this.tool = 'select';
    }
  }
}
