    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    border: 1px dashed #000;
    border-radius: 50%;
    pointer-events: none;
}
```

### JavaScript
Finally, add the JavaScript to handle the slider input and update the circle's radius.

```javascript
document.addEventListener('DOMContentLoaded', function() {
    const circle = document.getElementById('circle');
    const radiusSlider = document.getElementById('radius-slider');
    const concentricCircles = [20, 40, 60, 80, 100]; // Define the radii for concentric circles

    // Create concentric circles
    concentricCircles.forEach(radius => {
        const circleElement = document.createElement('div');
        circleElement.classList.add('concentric-circle');
        circleElement.style.width = `${radius * 2}px`;
        circleElement.style.height = `${radius * 2}px`;
