Merging Word documents using the OpenXML SDK in C# can be a complex task, especially when you need to selectively merge parts of the documents while preserving specific elements like headers, footers, and styles. Below is a C# function that demonstrates how to achieve this. This function assumes you have the OpenXML SDK installed in your project.

First, you need to install the OpenXML SDK via NuGet Package Manager:
```
Install-Package DocumentFormat.OpenXml
```

Here is the function to merge two Word documents as per your requirements:

```csharp
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;
using System;
using System.Collections.Generic;
using System.Linq;

public class WordDocumentMerger
{
    public static void MergeDocuments(string firstDocPath, string secondDocPath, string outputDocPath)
    {
        using (WordprocessingDocument firstDoc = WordprocessingDocument.Open(firstDocPath, false))
        using (WordprocessingDocument secondDoc = WordprocessingDocument.Open(secondDocPath, false))
        using (WordprocessingDocument outputDoc = WordprocessingDocument.Create(outputDocPath, DocumentFormat.OpenXml.WordprocessingDocumentType.Document))
        {
            // Clone the main document part from the first document
            MainDocumentPart mainPart = outputDoc.AddMainDocumentPart();
            mainPart.Document = firstDoc.MainDocumentPart.Document.CloneNode(true);

            // Clone the styles part from the first document
            if (firstDoc.MainDocumentPart.StyleDefinitionsPart != null)
            {
                StyleDefinitionsPart stylePart = mainPart.AddNewPart<StyleDefinitionsPart>();
                stylePart.FeedData(firstDoc.MainDocumentPart.StyleDefinitionsPart.GetStream());
            }

            // Clone the header and footer parts from the first document
            if (firstDoc.MainDocumentPart.HeaderParts.Any())
            {
                foreach (HeaderPart headerPart in firstDoc.MainDocumentPart.HeaderParts)
                {
                    HeaderPart newHeaderPart = mainPart.AddNewPart<HeaderPart>();
                    newHeaderPart.FeedData(headerPart.GetStream());
                }
            }

            if (firstDoc.MainDocumentPart.FooterParts.Any())
            {
                foreach (FooterPart footerPart in firstDoc.MainDocumentPart.FooterParts)
                {
                    FooterPart newFooterPart = mainPart.AddNewPart<FooterPart>();
                    newFooterPart.FeedData(footerPart.GetStream());
                }
            }

            // Clone the glossary document part from the second document
            if (secondDoc.MainDocumentPart.GlossaryDocumentPart != null)
            {
                GlossaryDocumentPart glossaryPart = mainPart.AddNewPart<GlossaryDocumentPart>();
                glossaryPart.FeedData(secondDoc.MainDocumentPart.GlossaryDocumentPart.GetStream());
            }

            // Add the first 2 pages from the first document
            Body body = mainPart.Document.Body;
            List<OpenXmlElement> firstDocElements = body.Elements().ToList();
            int elementsToTake = 0;
            int pageCount = 0;

            foreach (OpenXmlElement element in firstDocElements)
            {
                if (element is Paragraph para && para.Descendants<Break>().Any(b => b.Type == BreakValues.Page))
                {
                    pageCount++;
                }

                if (pageCount <= 2)
                {
                    elementsToTake++;
                }
                else
                {
                    break;
                }
            }

            body.RemoveAllChildren();
            for (int i = 0; i < elementsToTake; i++)
            {
                body.AppendChild(firstDocElements[i].CloneNode(true));
            }

            // Add the contents from the second document
            Body secondBody = secondDoc.MainDocumentPart.Document.Body;
            List<OpenXmlElement> secondDocElements = secondBody.Elements().ToList();

            foreach (OpenXmlElement element in secondDocElements)
            {
                body.AppendChild(element.CloneNode(true));
            }

            // Save the merged document
            mainPart.Document.Save();
        }
    }
}
```

### Explanation:
1. **Open and Clone Parts**: The function opens the first and second documents and creates a new output document. It then clones the main document part, styles part, header parts, and footer parts from the first document to the output document.
2. **Glossary Document**: The glossary document part from the second document is cloned to the output document.
3. **First 2 Pages**: The function iterates through the elements of the first document's body to count the pages and take the first 2 pages.
4. **Content from Second Document**: The function appends the contents of the second document's body to the output document's body.
5. **Save the Document**: Finally, the merged document is saved to the specified output path.

This function should meet your requirements for merging the specified parts of the documents while preserving the necessary elements.

