import java.util.List;
import java.util.NoSuchElementException;

public class SingleEntryChecker {

    public static <T> T checkSingleEntry(List<T> list) {
        return list.stream()
                .reduce((first, second) -> {
                    throw new IllegalStateException("List contains more than one entry");
                })
                .orElse(null);
    }

    public static void main(String[] args) {
        // Test cases
        List<String> singleEntryList = List.of("one");
        List<String> emptyList = List.of();
        List<String> multipleEntryList = List.of("one", "two");

        try {
            System.out.println("Single entry list: " + checkSingleEntry(singleEntryList)); // Should print "one"
            System.out.println("Empty list: " + checkSingleEntry(emptyList)); // Should print "null"
            System.out.println("Multiple entry list: " + checkSingleEntry(multipleEntryList)); // Should throw exception
        } catch (IllegalStateException e) {
            System.err.println("Exception: " + e.getMessage());
        }
    }
}
```

