class TCPHeader {
    sourcePort: number;
    destinationPort: number;
    sequenceNumber: number;
    acknowledgmentNumber: number;
    dataOffset: number;
    flags: {
        NS: boolean;
        CWR: boolean;
        ECE: boolean;
        URG: boolean;
        ACK: boolean;
        PSH: boolean;
        RST: boolean;
        SYN: boolean;
        FIN: boolean;
    };
    windowSize: number;
    checksum: number;
    urgentPointer: number;

    constructor(data: Uint8Array) {
        if (data.length < 20) {
            throw new Error('TCP header must be at least 20 bytes long');
        }

        this.sourcePort = (data[0] << 8) | data[1];
        this.destinationPort = (data[2] << 8) | data[3];
        this.sequenceNumber = (data[4] << 24) | (data[5] << 16) | (data[6] << 8) | data[7];
        this.acknowledgmentNumber = (data[8] << 24) | (data[9] << 16) | (data[10] << 8) | data[11];

        const headerLengthAndFlags = (data[12] << 8) | data[13];
        this.dataOffset = (headerLengthAndFlags >> 12) * 4;
        this.flags = {
            NS: (headerLengthAndFlags & 0x0100) !== 0,
            CWR: (headerLengthAndFlags & 0x0080) !== 0,
            ECE: (headerLengthAndFlags & 0x0040) !== 0,
            URG: (headerLengthAndFlags & 0x0020) !== 0,
            ACK: (headerLengthAndFlags & 0x0010) !== 0,
            PSH: (headerLengthAndFlags & 0x0008) !== 0,
            RST: (headerLengthAndFlags & 0x0004) !== 0,
            SYN: (headerLengthAndFlags & 0x0002) !== 0,
            FIN: (headerLengthAndFlags & 0x0001) !== 0
        };

        this.windowSize = (data[14] << 8) | data[15];
        this.checksum = (data[16] << 8) | data[17];
        this.urgentPointer = (data[18] << 8) | data[19];
    }

    toString(): string {
        return `TCP Header:
