```javascript
function retryRequest(url, attempts = 3) {
    return new Promise((resolve, reject) => {
        if (attempts <= 0) {
            reject(new Error('All attempts failed'));
            return;
        }

        fetch(url)
            .then(response => {
                if (response.ok) {
                    resolve(response);
                } else {
                    // Retry if the response is not ok
                    console.log(`Attempt ${4 - attempts} failed. Retrying...`);
                    retryRequest(url, attempts - 1).then(resolve).catch(reject);
                }
            })
            .catch(error => {
                // Retry if there is a network error
                console.log(`Attempt ${4 - attempts} failed. Retrying...`);
                retryRequest(url, attempts - 1).then(resolve).catch(reject);
            });
    });
}

// Example usage:
retryRequest('https://api.example.com/data')
    .then(response => {
        response.json().then(data => {
            console.log('Success:', data);
        });
    })
    .catch(error => {
        console.error('Failed:', error);
    });
```

