        *ledA = 0;
        ThisThread::sleep_for(1500ms);
        printf("My pointer is %p\n", (void*)ledA);
    }
}

// main() runs in its own thread in the OS
int main() {
    thread2.start(callback(ledAny, &ledYellow, &thread2_running));
    ThisThread::sleep_for(1000ms);
    thread3.start(callback(ledAny, &ledAmber, &thread3_running));

    while (true) {
        counter++;

        ledRed.write(true);
        ThisThread::sleep_for(500ms);
        ledRed.write(false);
        ThisThread::sleep_for(500ms);

        if (counter > 20) {
            thread2_running = false;  // Signal thread2 to stop
            thread2.join();           // Wait for thread2 to finish
            thread3_running = false;  // Signal thread3 to stop
            thread3.join();           // Wait for thread3 to finish
            break;                    // Exit the loop
        }
    }

    return 0;
}
