To create a simple MNIST handwritten digit recognition neural network using Vitis HLS (High-Level Synthesis), we will outline a basic structure of a feedforward neural network. The following code represents a simplified version of a neural network designed to classify MNIST digits. 

This example assumes you have a trained model and that you are implementing the inference part in Vitis HLS. The neural network will have an input layer of size 784 (28x28 pixels), a hidden layer with size 128, and an output layer with size 10 (for digits 0-9).

### Vitis HLS Code Example

```cpp
#include <hls_stream.h>
#include <ap_int.h>
#include <math.h>

#define INPUT_SIZE 784
#define HIDDEN_SIZE 128
#define OUTPUT_SIZE 10

// Activation function (ReLU)
float relu(float x) {
    return x > 0 ? x : 0;
}

// Softmax function for output layer
void softmax(float input[OUTPUT_SIZE], float output[OUTPUT_SIZE]) {
    float max_val = input[0];
    for (int i = 1; i < OUTPUT_SIZE; i++) {
        if (input[i] > max_val) {
            max_val = input[i];
        }
    }

    float sum = 0.0;
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        output[i] = exp(input[i] - max_val);
        sum += output[i];
    }

    for (int i = 0; i < OUTPUT_SIZE; i++) {
        output[i] /= sum;
    }
}

// Fully connected layer
void fully_connected(float input[INPUT_SIZE], float weights[HIDDEN_SIZE][INPUT_SIZE], float biases[HIDDEN_SIZE], float output[HIDDEN_SIZE]) {
    for (int i = 0; i < HIDDEN_SIZE; i++) {
        output[i] = biases[i];
        for (int j = 0; j < INPUT_SIZE; j++) {
            output[i] += weights[i][j] * input[j];
        }
        output[i] = relu(output[i]);
    }
}

// Output layer
void output_layer(float input[HIDDEN_SIZE], float weights[OUTPUT_SIZE][HIDDEN_SIZE], float biases[OUTPUT_SIZE], float output[OUTPUT_SIZE]) {
    for (int i = 0; i < OUTPUT_SIZE; i++) {
        output[i] = biases[i];
        for (int j = 0; j < HIDDEN_SIZE; j++) {
            output[i] += weights[i][j] * input[j];
        }
    }
    softmax(output, output);
}

// Top-level function
void mnist_nn(float input[INPUT_SIZE], 
              float hidden_weights[HIDDEN_SIZE][INPUT_SIZE], 
              float hidden_biases[HIDDEN_SIZE], 
              float output_weights[OUTPUT_SIZE][HIDDEN_SIZE], 
              float output_biases[OUTPUT_SIZE], 
              float output[OUTPUT_SIZE]) {

    float hidden_output[HIDDEN_SIZE];

    // Fully connected layer (input to hidden)
    fully_connected(input, hidden_weights, hidden_biases, hidden_output);

    // Output layer (hidden to output)
    output_layer(hidden_output, output_weights, output_biases, output);
}
```

