function makeRequestWithRetry(url, options, retries = 3) {
    return new Promise((resolve, reject) => {
        // Function to perform the fetch request
        const attemptRequest = (attempt) => {
            fetch(url, options)
                .then(response => {
                    if (!response.ok) {
                        throw new Error('Network response was not ok');
                    }
                    return response.json(); // or response.text() based on your needs
                })
                .then(data => resolve(data)) // Resolve the promise with the data
                .catch(error => {
                    if (attempt < retries) {
                        console.log(`Attempt ${attempt + 1} failed. Retrying...`);
                        attemptRequest(attempt + 1); // Recursive call to retry
                    } else {
                        reject(error); // Reject the promise after all attempts have failed
                    }
                });
        };

        attemptRequest(0); // Start the first attempt
    });
}

// Usage example:
