In your `MessagesViewController.swift`, you will create a custom view with two buttons. Here’s how you can do it:

```swift
import Messages

class MessagesViewController: MSMessagesAppViewController {

    override func viewDidLoad() {
        super.viewDidLoad()

        // Set up the buttons
        setupButtons()
    }

    private func setupButtons() {
        // Create a stack view to hold the buttons
        let stackView = UIStackView()
        stackView.axis = .horizontal
        stackView.distribution = .fillEqually
        stackView.spacing = 10

        // Create the first button
        let button1 = UIButton(type: .system)
        button1.setTitle("Button 1", for: .normal)
        button1.addTarget(self, action: #selector(button1Tapped), for: .touchUpInside)

        // Create the second button
        let button2 = UIButton(type: .system)
        button2.setTitle("Button 2", for: .normal)
        button2.addTarget(self, action: #selector(button2Tapped), for: .touchUpInside)

        // Add buttons to the stack view
        stackView.addArrangedSubview(button1)
        stackView.addArrangedSubview(button2)

        // Set up the stack view layout
        stackView.translatesAutoresizingMaskIntoConstraints = false
        view.addSubview(stackView)

        // Center the stack view in the view
        NSLayoutConstraint.activate([
            stackView.centerXAnchor.constraint(equalTo: view.centerXAnchor),
            stackView.centerYAnchor.constraint(equalTo: view.centerYAnchor),
            stackView.widthAnchor.constraint(equalTo: view.widthAnchor, multiplier: 0.8),
            stackView.heightAnchor.constraint(equalToConstant: 50)
