  private handleACK(header: TCPHeader): void {
    // Update sequence number and acknowledgment number
    this.seqNum = header.ackNum;
    this.ackNum = header.seqNum + header.dataLength;

    // Process received data
    const data = packet.subarray(20);
    this.buffer.set(data, this.ackNum - header.seqNum);
  }

  private handleFIN(header: TCPHeader): void {
    // Send ACK response
    const response = new Uint8Array(20);
    response[0] = (header.dstPort >> 8) & 0xFF;
    response[1] = header.dstPort & 0xFF;
    response[2] = (header.srcPort >> 8) & 0xFF;
    response[3] = header.srcPort & 0xFF;
    response[4] = (this.seqNum >> 24) & 0xFF;
    response[5] = (this.seqNum >> 16) & 0xFF;
    response[6] = (this.seqNum >> 8) & 0xFF;
    response[7] = this.seqNum & 0xFF;
    response[8] = (header.seqNum + 1 >> 24) & 0xFF;
    response[9] = (header.seqNum + 1 >> 16) & 0xFF;
    response[10] = (header.seqNum + 1 >> 8) & 0xFF;
    response[11] = (header.seqNum + 1) & 0xFF;
    response[12] = TCPFlags.ACK;
    response[15] = 0; // Checksum (todo)
    response[16] = 0; // Checksum (todo)
    this.socket.send(response);

    // Close connection
    console.log("Connection closed");
  }

  private handleRST(header: TCPHeader): void {
    // Close connection
    console.log("Connection reset");
  }

  public sendData(data: Uint8Array): void {
    const packet = new Uint8Array(20 + data.length);
    packet[0] = (this.socket.dstPort >> 8) & 0xFF;
    packet[1] = this.socket.dstPort & 0xFF;
    packet[2] = (this.socket.srcPort >> 8) & 0xFF;
    packet[3] = this.socket.srcPort & 0xFF;
    packet[4] = (this.seqNum >> 24) & 0xFF;
    packet[5] = (this.seqNum >> 16) & 0xFF;
    packet[6] = (this.seqNum >> 8) & 0xFF;
    packet[7] = this.seqNum & 0xFF;
    packet[8] = (this.ackNum >> 24) & 0xFF;
    packet[9] = (this.ackNum >> 16) & 0xFF;
    packet[10] = (this.ackNum >> 8) & 0xFF;
    packet[11] = this.ackNum & 0xFF;
    packet[12] = TCPFlags.PSH | TCPFlags.ACK;
    packet.set(data, 20);
    this.socket.send(packet);
    this.seqNum += data.length;
  }
}

enum TCPFlags {
  FIN = 0x01,
  SYN = 0x02,
  RST = 0x04,
  PSH = 0x08,
  ACK = 0x10,
  URG = 0x20,
}

interface TCPHeader {
  srcPort: number;
  dstPort: number;
  seqNum: number;
  ackNum: number;
  flags: number;
  windowSize: number;
  checksum: number;
  urgPtr: number;
  dataLength: number;
