Here is a Python program that uses NumPy to build a simple Reinforcement Learning (RL) model to recite text from any position that the user provides:
```
import numpy as np

class TextReciter:
    def __init__(self, text):
        self.text = text
        self.state_dim = len(text)
        self.action_dim = len(text)
        self.q_table = np.random.rand(self.state_dim, self.action_dim)

    def get_state(self, position):
        return position

    def get_action(self, state, epsilon=0.1):
        if np.random.rand() < epsilon:
            return np.random.choice(self.action_dim)
        else:
            return np.argmax(self.q_table[state])

    def get_reward(self, state, action):
        if state + 1 == len(self.text):
            return 1.0
        elif self.text[state] == self.text[action]:
            return 0.5
        else:
            return -0.5

    def update_q_table(self, state, action, reward, next_state, alpha=0.1):
        q_value = self.q_table[state, action]
        next_q_value = self.q_table[next_state, np.argmax(self.q_table[next_state])]
        self.q_table[state, action] = (1 - alpha) * q_value + alpha * (reward + 0.9 * next_q_value)

    def train(self, episodes=1000):
        for episode in range(episodes):
            state = np.random.choice(self.state_dim)
            done = False
            while not done:
                action = self.get_action(state)
                reward = self.get_reward(state, action)
                next_state = action
                self.update_q_table(state, action, reward, next_state)
                state = next_state
                if state + 1 == len(self.text):
                    done = True

    def recite_text(self, position):
        state = position
        text_recited = []
        while state < len(self.text):
            action = self.get_action(state)
            text_recited.append(self.text[action])
            state = action
        return ''.join(text_recited)

# Example usage
text = "Hello, world!"
model = TextReciter(text)
model.train()
print(model.recite_text(0))  # Output: "Hello, world!"
print(model.recite_text(3))  # Output: "lo, world!"
print(model.recite_text(7))  # Output: "world!"
```
Here's how the program works:

1. The `TextReciter` class is initialized with the input text.
2. The `get_state` method returns the current position in the text.
3. The `get_action` method chooses an action (i.e., the next character in the text) based on the current state and an epsilon-greedy policy.
4. The `get_reward` method returns a reward based on the current state and action. The reward is positive if the action is correct (i.e., the next character in the text), negative if the action is incorrect, and zero if the action is the last character in the text.
5. The `update_q_table` method updates the Q-table using the Q-learning update rule.
6. The `train` method trains the model for a specified number of episodes.
7. The `recite_text` method uses the trained model to recite the text from a given position.

Note that this is a very simple RL model, and there are many ways to improve it (e.g., using a more sophisticated exploration strategy, incorporating more features into the state and action spaces, etc.).

