import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Base64;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

public class KubernetesClient {

    private static final String API_PREFIX = "/api/v1";
    private static final String NAMESPACES_PATH = "/namespaces";
    private static final String PODS_PATH = "/pods";
    private static final String LOGS_PATH = "/log";

    private final String kubernetesApiServerUrl;
    private final String namespace;
    private final String bearerToken;
    private final HttpClient httpClient;

    public KubernetesClient(String kubernetesApiServerUrl, String namespace, String bearerToken) {
        this.kubernetesApiServerUrl = kubernetesApiServerUrl;
        this.namespace = namespace;
        this.bearerToken = bearerToken;
        this.httpClient = HttpClient.newHttpClient();
    }

    public String getPodLogs(String podName) throws IOException, InterruptedException {
        String url = kubernetesApiServerUrl + API_PREFIX + NAMESPACES_PATH + "/" + namespace + PODS_PATH + "/" + podName + LOGS_PATH;
        HttpRequest request = HttpRequest.newBuilder()
                .uri(URI.create(url))
                .header("Authorization", "Bearer " + bearerToken)
                .GET()
                .build();

        HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());

        if (response.statusCode() == 200) {
            return response.body();
        } else {
            throw new IOException("Failed to retrieve pod logs. Status code: " + response.statusCode());
        }
    }
}
```

