class Tcp {
  private sourcePort: number;
  private destinationPort: number;
  private sequenceNumber: number;
  private acknowledgementNumber: number;

  constructor(sourcePort: number, destinationPort: number, sequenceNumber: number, acknowledgementNumber: number) {
    this.sourcePort = sourcePort;
    this.destinationPort = destinationPort;
    this.sequenceNumber = sequenceNumber;
    this.acknowledgementNumber = acknowledgementNumber;
  }

  public parse(packet: Uint8Array): TcpPacket {
    const tcpPacket: TcpPacket = {
      sourcePort: (packet[0] << 8) | packet[1],
      destinationPort: (packet[2] << 8) | packet[3],
      sequenceNumber: (packet[4] << 24) | (packet[5] << 16) | (packet[6] << 8) | packet[7],
      acknowledgementNumber: (packet[8] << 24) | (packet[9] << 16) | (packet[10] << 8) | packet[11],
      dataOffset: (packet[12] >> 4) * 4,
      reserved: (packet[12] & 0x0f) << 4,
      flags: packet[13],
      windowSize: (packet[14] << 8) | packet[15],
      checksum: (packet[16] << 8) | packet[17],
      urgentPointer: (packet[18] << 8) | packet[19],
      options: [],
      data: new Uint8Array(),
    };

    // Parse TCP options
    for (let i = 20; i < tcpPacket.dataOffset; i += 2) {
      const optionId = packet[i];
      const optionLength = packet[i + 1];
      const optionValue = packet.slice(i + 2, i + 2 + optionLength);
      tcpPacket.options.push({ id: optionId, length: optionLength, value: optionValue });
    }

    // Parse TCP data
    tcpPacket.data = packet.slice(tcpPacket.dataOffset);

    return tcpPacket;
  }

  public create(packet: TcpPacket): Uint8Array {
    const tcpData = new Uint8Array(packet.data.length);
    packet.data.copy(tcpData);

    const tcpLength = 20 + packet.options.reduce((acc, option) => acc + option.length + 2, 0) + packet.data.length;
    const tcpPacket = new Uint8Array(tcpLength);

    // Set TCP source and destination ports
    tcpPacket[0] = packet.sourcePort >> 8;
    tcpPacket[1] = packet.sourcePort & 0xff;
    tcpPacket[2] = packet.destinationPort >> 8;
    tcpPacket[3] = packet.destinationPort & 0xff;

    // Set TCP sequence and acknowledgement numbers
    tcpPacket[4] = packet.sequenceNumber >> 24;
    tcpPacket[5] = (packet.sequenceNumber >> 16) & 0xff;
    tcpPacket[6] = (packet.sequenceNumber >> 8) & 0xff;
    tcpPacket[7] = packet.sequenceNumber & 0xff;
    tcpPacket[8] = packet.acknowledgementNumber >> 24;
    tcpPacket[9] = (packet.acknowledgementNumber >> 16) & 0xff;
    tcpPacket[10] = (packet.acknowledgementNumber >> 8) & 0xff;
    tcpPacket[11] = packet.acknowledgementNumber & 0xff;

    // Set TCP data offset, reserved, and flags
    tcpPacket[12] = (this.getDataOffset(packet) >> 4) & 0xf0;
    tcpPacket[13] = packet.flags;

    // Set TCP window size, checksum, and urgent pointer
    tcpPacket[14] = packet.windowSize >> 8;
    tcpPacket[15] = packet.windowSize & 0xff;
    tcpPacket[16] = packet.checksum >> 8;
    tcpPacket[17] = packet.checksum & 0xff;
    tcpPacket[18] = packet.urgentPointer >> 8;
    tcpPacket[19] = packet.urgentPointer & 0xff;

    // Set TCP options
    let optionIndex = 20;
    for (const option of packet.options) {
      tcpPacket[optionIndex] = option.id;
      tcpPacket[optionIndex + 1] = option.length;
      option.value.copy(tcpPacket, optionIndex + 2);
      optionIndex += option.length + 2;
    }

    // Set TCP data
    tcpData.copy(tcpPacket, optionIndex);

    return tcpPacket;
  }

  private getDataOffset(packet: TcpPacket): number {
    return 20 + packet.options.reduce((acc, option) => acc + option.length + 2, 0);
