use lazy_static::lazy_static;
use std::sync::Mutex;

lazy_static! {
    static ref PRIMES: Mutex<Vec<u64>> = Mutex::new(Vec::new());
}

struct PrimeStream {
    index: usize,
}

impl PrimeStream {
    fn new() -> Self {
        PrimeStream { index: 0 }
    }
}

impl Iterator for PrimeStream {
    type Item = u64;

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            let mut primes = PRIMES.lock().unwrap();
            if self.index < primes.len() {
                self.index += 1;
                return Some(primes[self.index - 1]);
            }

            let mut i = *primes.last().unwrap() + 1;
            while !is_prime(i) {
                i += 1;
            }

            primes.push(i);
            self.index += 1;
            return Some(i);
        }
    }
}

