```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

void handle_sigint(int sig) {
  printf("Caught SIGINT, exiting...\n");
  exit(0);
}

int main() {
  // Install signal handler for SIGINT (Ctrl+C)
  signal(SIGINT, handle_sigint);

  int pipe_fd[2];
  if (pipe(pipe_fd) == -1) {
    perror("pipe");
    exit(1);
  }

  pid_t child_pid = fork();
  if (child_pid == -1) {
    perror("fork");
    exit(1);
  } else if (child_pid == 0) { // Child process
    close(pipe_fd[0]); // Close read end
    char buffer[1024];
    // Write to pipe
    while (fgets(buffer, sizeof(buffer), stdin) != NULL) {
      write(pipe_fd[1], buffer, strlen(buffer));
    }
    close(pipe_fd[1]);
    exit(0);
  } else { // Parent process
    close(pipe_fd[1]); // Close write end
    char buffer[1024];
    while (1) {
      ssize_t bytes_read = read(pipe_fd[0], buffer, sizeof(buffer));
      if (bytes_read == -1) {
        if (errno == EINTR) {
          printf("Read interrupted by a signal, retrying...\n");
          continue; // Restart read operation
        } else {
          perror("read");
          exit(1);
        }
      } else if (bytes_read == 0) {
        printf("Child process exited.\n");
        break; // Child process finished writing
      } else {
        buffer[bytes_read] = '\0'; // Null-terminate the string
        printf("Read from pipe: %s", buffer);
      }
    }
    close(pipe_fd[0]);
    wait(NULL); // Wait for child process to exit
    return 0;
  }
}
```

**Explanation:**

1. **Signal Handling:**
   - `signal(SIGINT, handle_sigint)` sets up a handler for SIGINT (Ctrl+C) that prints a message and exits the program.

2. **Pipe Creation:**
   - `pipe(pipe_fd)` creates a pipe between the parent and child processes.

3. **Forking:**
   - `fork()` creates a child process.
   - In the child process:
     - `close(pipe_fd[0])` closes the read end of the pipe.
     - It reads from `stdin` and writes to `pipe_fd[1]` (write end).

   - In the parent process:
     - `close(pipe_fd[1])` closes the write end of the pipe.
     - It reads from `pipe_fd[0]` (read end).

4. **`read()` with EINTR Handling:**
   - The `while (1)` loop in the parent process continuously reads from the pipe.
   - `ssize_t bytes_read = read(pipe_fd[0], buffer, sizeof(buffer))`:
     - If `read()` returns `-1`:
       - `if (errno == EINTR)` checks if the error was caused by a signal interruption (like Ctrl+C).
       - If it is, the loop continues (`continue`) to retry the read operation. This ensures that the program doesn't crash due to a single signal interruption.
     - If `bytes_read` is `0`, it means the child process has finished writing.
     - If `bytes_read` is positive, it means data was read successfully, and it's printed to the console.

5. **Waiting for Child:**
   - `wait(NULL)` waits for the child process to exit.



