$maxRunningCoroutines = 5;
$semaphore = new \React\Promise\Semaphore($maxRunningCoroutines);

function runJob(LoopInterface $loop, callable $jobFunction): Promise
{
    return $semaphore->acquire()
        ->then(function () use ($loop, $jobFunction) {
            return new Promise(function (callable $resolve, callable $reject) use ($loop, $jobFunction) {
                $loop->addTimer(0, function () use ($jobFunction, $resolve, $reject) {
                    try {
                        $jobFunction();
                        $resolve();
                    } catch (\Exception $e) {
                        $reject($e);
                    }
                });
            });
        })
        ->finally(function () use ($semaphore) {
            $semaphore->release();
        });
}

