                this.canvas.addEventListener('mousemove', this.onMouseMove.bind(this));
                this.canvas.addEventListener('mouseup', this.onMouseUp.bind(this));
                this.drawing = false;
            }

            onMouseDown(event) {
                this.drawing = true;
                this.drawPixel(event.clientX, event.clientY);
            }

            onMouseMove(event) {
                if (!this.drawing) return;
                this.drawPixel(event.clientX, event.clientY);
            }

            onMouseUp() {
                this.drawing = false;
