                const pixelSize = 16;
                const posX = Math.floor((x - rect.left) / pixelSize) * pixelSize;
                const posY = Math.floor((y - rect.top) / pixelSize) * pixelSize;
                this.ctx.fillStyle = 'black';
                this.ctx.fillRect(posX, posY, pixelSize, pixelSize);
            }
        }

