my $preset = "";
my $resize = "";
my $noise = "";
my $input_file = "";

# Parse command-line arguments
while (my $arg = shift) {
  if ($arg eq "-q" || $arg eq "--quality") {
    $quality = shift;
  } elsif ($arg eq "-p" || $arg eq "--preset") {
    $preset = shift;
  } elsif ($arg eq "-r" || $arg eq "--resize") {
    $resize = shift;
  } elsif ($arg eq "-n" || $arg eq "--noise") {
    $noise = shift;
  } else {
    $input_file = $arg;
  }
}

# Check if input file exists
