public class ListChecker {

    public static <T> T checkList(List<T> list) {
        if (list.size() > 1) {
            throw new IllegalArgumentException("List cannot have more than one entry.");
        }

        return list.stream()
                .findFirst()
                .orElse(null);
    }

    public static void main(String[] args) {
        List<Integer> list1 = List.of(1);
        List<Integer> list2 = List.of(1, 2);
        List<Integer> list3 = List.of();

        System.out.println(checkList(list1)); // Output: 1
        try {
            System.out.println(checkList(list2)); // Throws IllegalArgumentException
        } catch (IllegalArgumentException e) {
            System.out.println(e.getMessage()); // Output: List cannot have more than one entry.
        }
        System.out.println(checkList(list3)); // Output: null
    }
}
