    public static List<string> ExtractHashtags(string text)
    {
        // Use a regular expression to find hashtags
        var hashtags = Regex.Matches(text, @"#[\w\d_]+")
                          .Cast<Match>()
                          .Select(m => m.Value)
                          .ToList();

        return hashtags;
    }

