Here's an example of a blocking read operation in C, using `read()` system call, that can be interrupted by a signal and correctly handles the `EINTR` error using a loop:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define BUFFER_SIZE 1024

void handle_signal(int signum) {
    /* Simply print the signal number and continue */
    printf("Received signal %d\n", signum);
}

int main() {
    char buffer[BUFFER_SIZE];
    int socket_fd, num_read;
    struct sigaction action;

    // Create a socket (replace with your actual socket setup)
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    // Set up a signal handler for SIGINT (Ctrl+C)
    action.sa_handler = handle_signal;
    action.sa_flags = 0;
    sigemptyset(&action.sa_mask);
    sigaction(SIGINT, &action, NULL);

    while (1) {
        // Block until data is available for reading
        num_read = read(socket_fd, buffer, BUFFER_SIZE - 1);
        if (num_read == -1) {
            if (errno == EINTR) {
                printf("Read interrupted, retrying...\n");
                continue;
            } else {
                perror("Read failed");
                exit(EXIT_FAILURE);
            }
        }

        // Add null terminator to the read data
        buffer[num_read] = '\0';

        // Process the read data
        printf("Read %d bytes: %s\n", num_read, buffer);

        // Break the loop if there's no more data
        if (num_read == 0) {
            printf("End of connection\n");
            break;
        }
    }

    close(socket_fd);
    return 0;
}
```

In this example, we create a simple socket and set up a signal handler for `SIGINT` (which is typically generated when the user presses Ctrl+C). The main loop reads data from the socket using `read()`. If `read()` is interrupted by a signal and `errno` is set to `EINTR`, the loop continues and retries the read operation. If `read()` fails for any other reason, the error is printed, and the program exits.

