```cpp
#include <iostream>
#include <string>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

#define PORT 888
#define MAX_PACKET_SIZE 1024

int main() {
    int server_socket, client_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    char packet[MAX_PACKET_SIZE];

    // Create a socket
    if ((server_socket = socket(AF_INET, SOCK_STREAM, 0)) == -1) {
        std::cerr << "Failed to create socket" << std::endl;
        return 1;
    }

    // Set the server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the port
    if (bind(server_socket, (struct sockaddr*)&server_addr, sizeof(server_addr)) == -1) {
        std::cerr << "Failed to bind socket" << std::endl;
        return 1;
    }

    // Listen for incoming connections
    if (listen(server_socket, 5) == -1) {
        std::cerr << "Failed to listen on socket" << std::endl;
        return 1;
    }

    std::cout << "Server is listening on port " << PORT << std::endl;

    // Accept a connection
    if ((client_socket = accept(server_socket, (struct sockaddr*)&client_addr, &client_addr_len)) == -1) {
        std::cerr << "Failed to accept connection" << std::endl;
        return 1;
    }

    std::cout << "Accepted connection from: " << inet_ntoa(client_addr.sin_addr) << ":" << ntohs(client_addr.sin_port) << std::endl;

    // Read packets from the client
    while (true) {
        int bytes_received = recv(client_socket, packet, MAX_PACKET_SIZE - 1, 0);
        if (bytes_received == -1) {
            std::cerr << "Failed to receive data" << std::endl;
            break;
        } else if (bytes_received == 0) {
            std::cout << "Client disconnected" << std::endl;
            break;
        }

        packet[bytes_received] = '\0';  // Null-terminate the packet for easier handling
        std::cout << "Received packet: " << packet << std::endl;
    }

    // Close the sockets
    close(client_socket);
    close(server_socket);

    return 0;
}
```
To compile and run the code:

```sh
g++ -std=c++11 -o server server.cpp -lpthread
./server
```

