static int __init map_memory_region(void)
{
    unsigned long virt_addr = VIRTUAL_ADDRESS;
    unsigned long phys_addr;
    struct page *page;
    pgprot_t prot;

    // Allocate a page in physical memory
    page = alloc_page(GFP_KERNEL);
