In C, when you call a blocking read function (like `read()` or `recv()`) and a signal is caught during the operation, the system call can be interrupted, causing the function to return `-1` and set the `errno` to `EINTR`. To handle this situation, you can use a loop to retry the read operation after the signal is caught. Here's an example using `read()`:

```c
#include <stdio.h>
#include <unistd.h>
#include <stdlib.h>
#include <sys/types.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>

void signal_handler(int signum) {
    // Handle the signal here, if needed
}

int main() {
    int fd = open("testfile.txt", O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        exit(EXIT_FAILURE);
    }

    char buffer[1024];
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to set signal handler");
        exit(EXIT_FAILURE);
    }

    while (true) {
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));
        if (bytes_read == -1) {
            if (errno == EINTR) {
                // Read operation was interrupted by a signal, retry
                continue;
            } else {
                perror("Failed to read from file");
                exit(EXIT_FAILURE);
            }
        } else if (bytes_read == 0) {
            // End of file reached
            printf("End of file reached\n");
            break;
        } else {
            // Data read successfully
            printf("Read %zd bytes: %s", bytes_read, buffer);
        }
    }

    close(fd);
    return 0;
}
```

In this example, the program opens a file and sets a signal handler for `SIGINT` (Ctrl+C). When the read operation is interrupted by a signal, the loop continues, and the read operation is retried. If the interruption is not due to a signal (`errno` is not `EINTR`), an error message is printed and the program exits.

