To merge Word documents using the OpenXML SDK, you'll need to create a new Word document and copy the relevant parts from both source documents. Here's an example of how to achieve this in C#:

1. First, make sure you have the Open XML SDK installed. You can add it to your project via NuGet by searching for "DocumentFormat.OpenXml".

2. Below is a sample function that demonstrates how to merge the specified parts from two documents:

```csharp
using DocumentFormat.OpenXml;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;
using System.IO;
using System.Linq;

public void MergeWordDocuments(string sourceDoc1Path, string sourceDoc2Path, string destinationDocPath)
{
    // Load the first document (sourceDoc1) for headers, footers, fonts, styles, and first 2 pages
    using var doc1 = WordprocessingDocument.Open(sourceDoc1Path, false);
    MainDocumentPart doc1MainPart = doc1.MainDocumentPart;

    // Load the second document (sourceDoc2) for page contents and glossary
    using var doc2 = WordprocessingDocument.Open(sourceDoc2Path, false);
    MainDocumentPart doc2MainPart = doc2.MainDocumentPart;

    // Create a new document to merge the content
    using var destinationDoc = WordprocessingDocument.Create(destinationDocPath, WordprocessingDocumentType.Document);
    MainDocumentPart destinationMainPart = destinationDoc.AddMainDocumentPart();

    // Copy headers, footers, fonts, and styles from doc1
    CopyParts(doc1MainPart, destinationMainPart, typeof(HeaderPart), typeof(FooterPart), typeof(StylesPart), typeof(FontsPart));

    // Create a new body for the merged document
    var newBody = new Body();

    // Copy the first 2 sections (paragraphs) from doc1
    int paragraphsCopied = 0;
    foreach (var element in doc1MainPart.Document.Body.Descendants()
        .Where(e => e.LocalName == "p"))
    {
        if (paragraphsCopied >= 2)
            break;
        newBody.AppendChild(element.CloneNode(true));
        paragraphsCopied++;
    }

    // Copy the rest of the content from doc2
    foreach (var element in doc2MainPart.Document.Body.Descendants())
    {
        newBody.AppendChild(element.CloneNode(true));
    }

    // Copy glossary from doc2 (assuming it's the last element)
    var glossary = doc2MainPart.Document.Body.Descendants().LastOrDefault();
    if (glossary != null)
    {
        newBody.AppendChild(glossary.CloneNode(true));
    }

    // Add the new body to the destination document
    destinationMainPart.Document = new Document(newBody);

    // Copy images from both source documents
    CopyImageParts(doc1MainPart, destinationMainPart);
    CopyImageParts(doc2MainPart, destinationMainPart);
}

private void CopyParts(MainDocumentPart sourcePart, MainDocumentPart destinationPart, params Type[] partTypes)
{
    foreach (var partType in partTypes)
    {
        var sourcePartReference = sourcePart.GetPartsOfType(partType).FirstOrDefault();
        if (sourcePartReference != null)
        {
            var destinationPartReference = destinationPart.AddPart(sourcePartReference.Clone(), sourcePartReference.Id);
            sourcePartReference.Delete();
        }
    }
}

private void CopyImageParts(MainDocumentPart sourcePart, MainDocumentPart destinationPart)
{
    foreach (var imagePart in sourcePart.ImageParts)
    {
        var newImagePart = destinationPart.AddImagePart(imagePart.ContentType, imagePart.Id);
        using var sourceStream = imagePart.GetStream();
        using var destinationStream = newImagePart.GetStream(FileMode.Create, FileAccess.Write);
        sourceStream.CopyTo(destinationStream);
    }
}
```

This code will create a new Word document at `destinationDocPath` with the merged content as specified. Make sure to replace the `sourceDoc1Path`, `sourceDoc2Path`, and `destinationDocPath` with the appropriate file paths.

