```

Create a new folder `src/components` and inside it, create a file named `TodoList.js`:

```javascript
import React, { useState, useEffect } from 'react';
import axios from 'axios';

const TodoList = () => {
  const [todos, setTodos] = useState([]);
  const [newTodo, setNewTodo] = useState('');

  useEffect(() => {
    async function fetchData() {
      const result = await axios.get('http://localhost:5000/api/todos');
      setTodos(result.data);
    }
    fetchData();
  }, []);

  const addTodo = async () => {
    await axios.post('http://localhost:5000/api/todos', { title: newTodo, completed: false });
    setNewTodo('');
    fetchData();
  };

  const toggleTodo = async (id) => {
    await axios.put(`http://localhost:5000/api/todos/${id}`, { completed: !todos.find((todo) => todo._id === id).completed });
    fetchData();
  };

  const deleteTodo = async (id) => {
    await axios.delete(`http://localhost:5000/api/todos/${id}`);
    fetchData();
  };

  return (
    <div>
      <input value={newTodo} onChange={(e) => setNewTodo(e.target.value)} />
      <button onClick={addTodo}>Add Todo</button>
      <ul>
        {todos.map((todo) => (
          <li key={todo._id}>
            {todo.title}{' '}
            <input
              type="checkbox"
              checked={todo.completed}
              onChange={() => toggleTodo(todo._id)}
            />
            <button onClick={() => deleteTodo(todo._id)}>Delete</button>
          </li>
