Creating a full Recurrent Neural Network (RNN) implementation in TypeScript from scratch would be quite extensive, but I can provide a simplified example using basic concepts. This example uses a basic RNN cell and doesn't include optimizations, libraries, or training functionality. You'll need to use libraries like TensorFlow.js for a complete and efficient solution.

```typescript
class SimpleRNNCell {
  constructor(hiddenSize: number, inputSize: number, learningRate: number) {
    this.hiddenSize = hiddenSize;
    this.inputSize = inputSize;
    this.learningRate = learningRate;

    // Initialize weights and biases with random values
    this.Wxh = new Float32Array(hiddenSize * inputSize);
    this.Whh = new Float32Array(hiddenSize * hiddenSize);
    this.bh = new Float32Array(hiddenSize);
    this.Wyh = new Float32Array(inputSize * hiddenSize);
    this.bh = new Float32Array(inputSize);

    this.randomizeWeights();
  }

  randomizeWeights() {
    const bound = 1 / Math.sqrt(this.hiddenSize);
    for (let i = 0; i < this.Wxh.length; i++) {
      this.Wxh[i] = Math.random() * 2 * bound - bound;
    }
    for (let i = 0; i < this.Whh.length; i++) {
      this.Whh[i] = Math.random() * 2 * bound - bound;
    }
    for (let i = 0; i < this.bh.length; i++) {
      this.bh[i] = Math.random() * 2 * bound - bound;
    }
    for (let i = 0; i < this.Wyh.length; i++) {
      this.Wyh[i] = Math.random() * 2 * bound - bound;
    }
    for (let i = 0; i < this.by.length; i++) {
      this.by[i] = Math.random() * 2 * bound - bound;
    }
  }

  forward(input: number[], prevHidden: number[]) {
    const hidden = new Float32Array(this.hiddenSize);
    const output = new Float32Array(this.inputSize);

    // Compute hidden state
    for (let j = 0; j < this.hiddenSize; j++) {
      let sum = 0;
      for (let i = 0; i < this.inputSize; i++) {
        sum += this.Wxh[j * this.inputSize + i] * input[i];
      }
      for (let i = 0; i < this.hiddenSize; i++) {
        sum += this.Whh[j * this.hiddenSize + i] * prevHidden[i];
      }
      sum += this.bh[j];
      hidden[j] = Math.tanh(sum);
    }

    // Compute output
    for (let j = 0; j < this.inputSize; j++) {
      let sum = 0;
      for (let i = 0; i < this.hiddenSize; i++) {
        sum += this.Wyh[j * this.hiddenSize + i] * hidden[i];
      }
      sum += this.by[j];
      output[j] = Math.sigmoid(sum);
    }

    return { hidden, output };
  }
}

// Usage:
const cell = new SimpleRNNCell(5, 3, 0.1);
const input = [0.1, 0.2, 0.3];
const prevHidden = [0.4, 0.5, 0.6, 0.7, 0.8];
const { hidden, output } = cell.forward(input, prevHidden);
console.log("Hidden state:", hidden);
console.log("Output:", output);
```

This code defines a `SimpleRNNCell` class with basic weight initialization and forward propagation for a single time step. It uses the tanh activation function for the hidden state and sigmoid for the output. Remember that this is a simplified example, and for real-world applications, you should consider using a library like TensorFlow.js or PyTorch.js.

