function findEntity(jsonObj, entityKey, path = []) {
  if (typeof jsonObj !== 'object' || jsonObj === null) {
    return null;
  }

  for (const key in jsonObj) {
    if (key === entityKey) {
      return { value: jsonObj[key], path: [...path, key] };
