Building a full Reinforcement Learning (RL) model to recite text from any position with only numpy would be quite complex, as it typically involves more than just numpy for RL tasks (such as state representation, action spaces, and model training). However, I can give you a simple implementation of a Q-Learning algorithm for a discrete action space problem. In this case, the RL model will learn to navigate through a text sequence.

```python
import numpy as np

# Define the environment
text = "Sample text to recite from any position"
total_chars = len(text)
states = range(total_chars)
actions = ['left', 'right']
rewards = {'left': -1, 'right': -1, 'correct': 1}
 terminals = [0, total_chars - 1]

class QLearningAgent:
    def __init__(self, learning_rate=0.1, discount_factor=0.9, exploration_rate=1.0, exploration_decay=0.99, min_exploration=0.01):
        self.q_table = np.zeros((total_chars, len(actions)))
        self.learning_rate = learning_rate
        self.discount_factor = discount_factor
        self.exploration_rate = exploration_rate
        self.exploration_decay = exploration_decay
        self.min_exploration = min_exploration

    def choose_action(self, state):
        if np.random.uniform(0, 1) < self.exploration_rate:
            return np.random.choice(actions)
        else:
            return np.argmax(self.q_table[state])

    def update_q_table(self, state, action, reward, next_state):
        max_future_q = np.max(self.q_table[next_state])
        current_q = self.q_table[state, action]
        new_q = (1 - self.learning_rate) * current_q + self.learning_rate * (reward + self.discount_factor * max_future_q)
        self.q_table[state, action] = new_q

    def decay_exploration_rate(self):
        self.exploration_rate *= self.exploration_decay
        self.exploration_rate = max(self.min_exploration, self.exploration_rate)

def play_episode(agent, state):
    done = False
    total_reward = 0
    while not done:
        action = agent.choose_action(state)
        if action == 'left':
            if state > 0:
                state -= 1
            else:
                total_reward -= rewards[action]
                done = True
        elif action == 'right':
            if state < total_chars - 1:
                state += 1
            else:
                total_reward += rewards[action]
                done = True
        else:
            raise ValueError("Invalid action")

        agent.update_q_table(state, action, total_reward, state)
        agent.decay_exploration_rate()

    return total_reward

def train_agent(agent, num_episodes):
    for episode in range(num_episodes):
        state = np.random.randint(total_chars)
        total_reward = play_episode(agent, state)
        print(f"Episode {episode}: Total Reward = {total_reward}")

# Initialize the agent and train
agent = QLearningAgent()
train_agent(agent, num_episodes=1000)
```

