        val measuredHeight = constraints.maxHeight
        val measuredWidth = constraints.maxWidth

        // Perform your custom measurement logic here, based on the available width and height
        // For example, you can define different breakpoints for different screen sizes

        return LayoutSize(measuredWidth, measuredHeight)
    }

