To compute the n-th Fibonacci number mod p, you can use the following JavaScript function. This implementation uses the closed-form expression for Fibonacci numbers based on the matrix exponential, which provides better performance for larger values of n.

```javascript
function fibonacci(n, p) {
 if (n === 0 || n === 1) return n;

 const alpha = (1 / sqrt(5)) * ((1 + Math.sqrt(5)) / 2);
 const beta = (1 / sqrt(5)) * ((1 - Math.sqrt(5)) / 2);
 const m = Math.ceil(Math.log(n) / Math.log((1 + Math.sqrt(5)) / 2));

 let a = alpha;
 let b = beta;
 let t = 1;
 for (let i = 1; i < m; i++) {
    t *= (n - i) / (i + 1);
    t %= p;
    a *= a;
    a %= p;
    b *= b;
    b %= p;
    if ((i & 1) === 1) {
      a += b;
      a %= p;
    }
    b -= a;
    b %= p;
 }

 if (n & 1) {
    return a;
 }

 return b;
}

function sqrt(x) {
 let x0 = x / 2;
 for (let i = 0; i < 10; i++) {
    const x1 = x0 + (x / (2 * x0));
    if (Math.abs(x1 - x0) < 1e-12) {
      return x1;
    }
    x0 = x1;
 }
 return x0;
}
```

This function first checks for the base cases (n = 0 or n = 1). Then, it calculates the alpha and beta values using the closed-form expression. The main calculation is performed in the for loop. The sqrt function is used to calculate the square root. The final result is returned depending on the parity of n.

Remember to test your code with various values of n and p to ensure it works as expected. If you are going to use this function for large values of n and p, you may consider using a BigInt version of the function to avoid integer overflows.

