```javascript
// backend/public/client.js

import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom';
import axios from 'axios';

function App() {
 const [tasks, setTasks] = useState([]);
 const [newTask, setNewTask] = useState('');

 useEffect(() => {
    axios.get('/api/tasks').then(res => {
      setTasks(res.data);
    });
 }, []);

 const handleAddTask = () => {
    axios.post('/api/tasks', { title: newTask }).then(res => {
      setTasks([...tasks, res.data]);
      setNewTask('');
    });
 };

 const handleDeleteTask = (id) => {
    axios.delete(`/api/tasks/${id}`).then(() => {
      setTasks(tasks.filter(task => task.id !== id));
    });
 };

 const handleUpdateTask = (id, event) => {
    const newTitle = event.target.value;
    axios.put(`/api/tasks/${id}`, { title: newTitle }).then(() => {
      setTasks(tasks.map(task => (task.id === id ? { ...task, title: newTitle } : task)));
    });
 };

 return (
    <div>
      <h1>To-Do List App</h1>
      <input type="text" value={newTask} onChange={event => setNewTask(event.target.value)} placeholder="Enter new task" />
      <button onClick={handleAddTask}>Add Task</button>
      <ul>
        {tasks.map(task => (
          <li key={task.id}>
            <input type="text" value={task.title} onChange={event => handleUpdateTask(task.id, event)} />
            <button onClick={() => handleDeleteTask(task.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
 );
}

ReactDOM.render(<App />, document.getElementById('root'));
```

5. Run the backend with the following command:

