void conv_layer(data_t input[IMG_DIM][IMG_DIM], weight_t kernel[L1_NUM_KERNELS][L1_KERNEL_SIZE][L1_KERNEL_SIZE], data_t output[L1_NUM_KERNELS][IMG_DIM - L1_KERNEL_SIZE + 1][IMG_DIM - L1_KERNEL_SIZE + 1]) {
