        for (int i = 0; i < IMG_DIM - L1_KERNEL_SIZE + 1; i++) {
            for (int j = 0; j < IMG_DIM - L1_KERNEL_SIZE + 1; j++) {
                accum_t sum = 0;
                for (int ki = 0; ki < L1_KERNEL_SIZE; ki++) {
                    for (int kj = 0; kj < L1_KERNEL_SIZE; kj++) {
                        sum += input[i + ki][j + kj] * kernel[k][ki][kj];
                    }
                }
                output[k][i][j] = sum;
            }
        }
    }
}
```

