    let primes = generate_primes(1000); // Generate primes up to 1000
    println!("Prime numbers up to 1000: {:?}", primes);
}


fn generate_primes(limit: usize) -> Vec<i32> {
    let mut primes = Vec::new();
    let mut number = 2;

    while number <= limit {
        if is_prime(number) {
            primes.push(number);
        }
        number += 1;
    }

    primes
}

fn is_prime(num: i32) -> bool {
    if num <= 1 {
        return false;
    }

    for i in 2..=(num as f64).sqrt() as usize {
        if num % i == 0 {
            return false;
        }
    }
    true 
}
