```c
#include <stdio.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define BUF_SIZE 1024

int main() {
    char buffer[BUF_SIZE];
    ssize_t bytes_read;

    while (1) {
        bytes_read = read(STDIN_FILENO, buffer, BUF_SIZE);

        if (bytes_read == -1) {
            if (errno == EINTR) {
                // Read was interrupted by a signal, retry
                continue;
            } else {
                perror("Error reading from stdin");
                return 1;
            }
        }

        // Process the read data
        printf("Read %zd bytes: %s\n", bytes_read, buffer);
    }

    return 0;
}
```

In this example, the `read` function is used to read input from the standard input (stdin). If the read operation is interrupted by a signal (such as pressing Ctrl+C), the `EINTR` error is detected and the read operation is retried until successful.

