```kotlin
import android.net.VpnService
import android.os.ParcelFileDescriptor
import java.net.Inet4Address
import java.net.InetSocketAddress
import java.nio.ByteBuffer
import java.nio.channels.DatagramChannel
import java.nio.channels.SelectionKey
import java.nio.channels.Selector
import java.nio.channels.spi.SelectorProvider

class FilterVPNService : VpnService() {

    private var vpnInterface: ParcelFileDescriptor? = null
    private var selector: Selector? = null

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        Thread {
            try {
                if (startVPN()) {
                    startVPNConnection()
                }
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }.start()

        return START_STICKY
    }

    private fun startVPN(): Boolean {
        val builder = Builder()
        builder.addAddress("10.0.0.1", 32)
        builder.addRoute("0.0.0.0", 0)
        vpnInterface = builder.establish()

        return true
    }

    private fun startVPNConnection() {
        selector = SelectorProvider.provider().openSelector()
        val vpnChannel = DatagramChannel.open()
        vpnChannel.socket().bind(InetSocketAddress("0.0.0.0", 8080))
        vpnChannel.configureBlocking(false)
        vpnChannel.register(selector, SelectionKey.OP_READ)

        while (true) {
            selector?.select()

            val selectedKeys = selector?.selectedKeys()
            val iterator = selectedKeys?.iterator()
            while (iterator?.hasNext() == true) {
                val key = iterator.next() as SelectionKey
                if (key.isReadable) {
                    val buffer = ByteBuffer.allocate(1500)
                    val client = DatagramChannel.open()
                    val clientChannel = client.connect(Inet4Address.getByName("YOUR_DESTINATION_IP_ADDRESS"), 80)
                    clientChannel.write(buffer)
                    clientChannel.close()
                }
                iterator.remove()
            }
        }
    }

    override fun onDestroy() {
        super.onDestroy()
        vpnInterface?.close()
        selector?.close()
    }
