```rust
fn is_prime(num: u64) -> bool {
    if num <= 1 {
        return false;
    }
    for i in 2..=num / 2 {
        if num % i == 0 {
            return false;
        }
    }
    true
}

struct PrimeStream {
    current: u64,
}

impl PrimeStream {
    fn new() -> PrimeStream {
        PrimeStream { current: 2 }
    }
}

impl Iterator for PrimeStream {
    type Item = u64;

    fn next(&mut self) -> Option<u64> {
        loop {
            if is_prime(self.current) {
                let prime = self.current;
                self.current += 1;
                return Some(prime);
            }
            self.current += 1;
        }
    }
}

fn main() {
    let mut prime_stream = PrimeStream::new();

    for _ in 0..10 {
        if let Some(prime) = prime_stream.next() {
            println!("{}", prime);
        }
    }
}
```

